def twoSum(nums, target):
    prevMap = {}
    for i in range(len(nums)):
        diff = target - nums[i]
        if diff in prevMap:
            return [prevMap[diff], i]
        prevMap[nums[i]] = i
    return []

nums = [2, 7, 11, 15]
print("Indices:", twoSum(nums, 9))

def containsDuplicate(nums):
    seen = set()
    for n in nums:
        if n in seen:
            return True
        seen.add(n)
    return False

print("Has duplicate:", containsDuplicate([1, 2, 3, 1]))

def isAnagram(s, t):
    if len(s) != len(t): return False
    countS = {}
    countT = {}
    for ch in s: countS[ch] = countS.get(ch, 0) + 1
    for ch in t: countT[ch] = countT.get(ch, 0) + 1
    return countS == countT

print("Is anagram:", isAnagram("anagram", "nagaram"))

def groupAnagrams(strs):
    ansMap = {}
    for s in strs:
        key = "".join(sorted(s))
        if key not in ansMap: ansMap[key] = []
        ansMap[key].append(s)
    return list(ansMap.values())

print("Groups:", groupAnagrams(["eat", "tea", "tan", "ate", "nat", "bat"]))

def topKFrequent(nums, k):
    count = {}
    for n in nums: count[n] = count.get(n, 0) + 1
    sorted_items = sorted(count.items(), key=lambda item: item[1], reverse=True)
    return [item[0] for item in sorted_items[:k]]

print("Top K:", topKFrequent([1, 1, 1, 2, 2, 3], 2))

def longestConsecutive(nums):
    numSet = set(nums)
    longest = 0
    for n in numSet:
        if (n - 1) not in numSet:
            length = 1
            while (n + length) in numSet: length += 1
            if length > longest: longest = length
    return longest

print("Longest streak:", longestConsecutive([100, 4, 200, 1, 3, 2]))

def findDisappearedNumbers(nums):
    for i in range(len(nums)):
        idx = abs(nums[i]) - 1
        if nums[idx] > 0: nums[idx] = -nums[idx]
    return [i + 1 for i in range(len(nums)) if nums[i] > 0]

print("Disappeared:", findDisappearedNumbers([4, 3, 2, 7, 8, 2, 3, 1]))

def missingNumber(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

print("Missing:", missingNumber([3, 0, 1]))

def moveZeroes(nums):
    w = 0
    for r in range(len(nums)):
        if nums[r] != 0:
            nums[w], nums[r] = nums[r], nums[w]
            w += 1
    return nums

