def plusOne(digits):
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        digits[i] = 0
    return [1] + digits

print("Plus one:", plusOne([1, 2, 9]))

def findMaxConsecutiveOnes(nums):
    max_c, curr = 0, 0
    for n in nums:
        if n == 1:
            curr += 1
            if curr > max_c: max_c = curr
        else: curr = 0
    return max_c

print("Max 1s:", findMaxConsecutiveOnes([1, 1, 0, 1, 1, 1]))

def subarraySum(nums, k):
    count, curr_sum = 0, 0
    prefix_map = {0: 1}
    for n in nums:
        curr_sum += n
        diff = curr_sum - k
        if diff in prefix_map: count += prefix_map[diff]
        prefix_map[curr_sum] = prefix_map.get(curr_sum, 0) + 1
    return count

print("Subarrays:", subarraySum([1, 1, 1], 2))

def findMaxLength(nums):
    max_len, balance = 0, 0
    seen = {0: -1}
    for i in range(len(nums)):
        balance += 1 if nums[i] == 1 else -1
        if balance in seen:
            l = i - seen[balance]
            if l > max_len: max_len = l
        else: seen[balance] = i
    return max_len

print("Max len:", findMaxLength([0, 1, 0, 0, 1, 1, 0]))

def rotateImage(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    for i in range(n):
        matrix[i].reverse()
    return matrix

