def setZeroes(matrix):
    m, n = len(matrix), len(matrix[0])
    first_col_zero = any(matrix[r][0] == 0 for r in range(m))
    for r in range(m):
        for c in range(1, n):
            if matrix[r][c] == 0:
                matrix[r][0] = 0; matrix[0][c] = 0
    for r in range(1, m):
        for c in range(1, n):
            if matrix[r][0] == 0 or matrix[0][c] == 0:
                matrix[r][c] = 0
    if matrix[0][0] == 0:
        for c in range(n): matrix[0][c] = 0
    if first_col_zero:
        for r in range(m): matrix[r][0] = 0
    return matrix

print("Zeroes:", setZeroes([[1,1,1],[1,0,1],[1,1,1]]))

def spiralOrder(matrix):
    res = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while left <= right and top <= bottom:
        for c in range(left, right + 1): res.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1): res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1): res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1): res.append(matrix[r][left])
            left += 1
    return res

print("Spiral:", spiralOrder([[1,2,3],[4,5,6],[7,8,9]]))

def sortColors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1; mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1
    return nums

print("Sorted:", sortColors([2, 0, 2, 1, 1, 0]))

def majorityElementII(nums):
    c1, c2, n1, n2 = None, None, 0, 0
    for n in nums:
        if n == c1: n1 += 1
        elif n == c2: n2 += 1
        elif n1 == 0: c1, n1 = n, 1
        elif n2 == 0: c2, n2 = n, 1
        else: n1 -= 1; n2 -= 1
    res = []
    if nums.count(c1) > len(nums) // 3: res.append(c1)
    if c2 != c1 and nums.count(c2) > len(nums) // 3: res.append(c2)
    return res

print("Majority > n/3:", majorityElementII([3, 2, 3]))

def firstMissingPositive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            t = nums[i] - 1
            nums[i], nums[t] = nums[t], nums[i]
    for i in range(n):
        if nums[i] != i + 1: return i + 1
    return n + 1

print("First missing:", firstMissingPositive([3, 4, -1, 1]))

def longestCommonPrefix(strs):
    if not strs: return ""
    p = strs[0]
    for s in strs[1:]:
        while not s.startswith(p):
            p = p[:-1]
            if not p: return ""
    return p

print("Prefix:", longestCommonPrefix(["flower","flow","flight"]))

def firstUniqChar(s):
    count = {}
    for ch in s: count[ch] = count.get(ch, 0) + 1
    for i, ch in enumerate(s):
        if count[ch] == 1: return i
    return -1

print("First unique:", firstUniqChar("leetcode"))

def isIsomorphic(s, t):
    if len(s) != len(t): return False
    mST, mTS = {}, {}
    for c1, c2 in zip(s, t):
        if (c1 in mST and mST[c1] != c2) or (c2 in mTS and mTS[c2] != c1):
            return False
        mST[c1] = c2; mTS[c2] = c1
    return True

print("Isomorphic:", isIsomorphic("egg", "add"))

def encode(strs):
    return "".join(str(len(s)) + "#" + s for s in strs)

def decode(s):
    res, i = [], 0
    while i < len(s):
        j = s.find("#", i)
        length = int(s[i:j])
        res.append(s[j + 1 : j + 1 + length])
        i = j + 1 + length
    return res

enc = encode(["neet","code"])
print("Decoded:", decode(enc))
